from qiskit import QuantumCircuit
import numpy as np

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n = len(problem_qubits)
    k = 2

    # Compute the vertex cover condition
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) in [(0, 1), (0, 2), (2, 3)]:
                qc.ccx(problem_qubits[i], problem_qubits[j], ancilla_qubits[0])

    # Check the size of the vertex cover
    for i in range(n):
        qc.cx(problem_qubits[i], ancilla_qubits[1])

    qc.mcp(np.pi / 2, [ancilla_qubits[1]], ancilla_qubits[2])

    for i in range(n):
        qc.cx(problem_qubits[i], ancilla_qubits[1])

    # Apply the phase flip if the vertex cover is valid
    qc.mcp(-np.pi / 2, [ancilla_qubits[0], ancilla_qubits[2]], ancilla_qubits[3])

    # Uncompute the vertex cover condition
    for i in range(n):
        for j in range(i+1, n):
            if (i, j) in [(0, 1), (0, 2), (2, 3)]:
                qc.ccx(problem_qubits[i], problem_qubits[j], ancilla_qubits[0])

    # Uncompute the size check
    for i in range(n):
        qc.cx(problem_qubits[i], ancilla_qubits[1])

    qc.mcp(np.pi / 2, [ancilla_qubits[1]], ancilla_qubits[2])

    for i in range(n):
        qc.cx(problem_qubits[i], ancilla_qubits[1])

