from qiskit import QuantumCircuit
import numpy as np

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n = len(problem_qubits)
    k = 3

    # Compute the adjacency matrix
    adj_matrix = np.zeros((n, n), dtype=int)
    edges = [(0, 1), (0, 2), (1, 2), (2, 3), (2, 4), (3, 4)]
    for u, v in edges:
        adj_matrix[u][v] = 1
        adj_matrix[v][u] = 1

    # Ancilla qubits for intermediate computations
    ancilla_index = 0

    # Apply the oracle logic
    for mask in range(1 << n):
        if bin(mask).count('1') > k:
            continue

        # Check if the current mask is a valid vertex cover
        valid_cover = True
        for u in range(n):
            for v in range(u + 1, n):
                if adj_matrix[u][v] == 1 and (mask & (1 << u)) == 0 and (mask & (1 << v)) == 0:
                    valid_cover = False
                    break
            if not valid_cover:
                break

        if valid_cover:
            # Apply phase -1 to the corresponding basis state
            for i in range(n):
                if mask & (1 << i):
                    qc.x(problem_qubits[i])
            qc.h(ancilla_qubits[ancilla_index])
            qc.mcp(np.pi, [problem_qubits[j] for j in range(n)], ancilla_qubits[ancilla_index])
            qc.h(ancilla_qubits[ancilla_index])
            for i in range(n):
                if mask & (1 << i):
                    qc.x(problem_qubits[i])

            ancilla_index += 1
