import numpy as np

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n_free_cells = len(problem_qubits) // 2
    rows = [0b101, 0b011, 0b_1_1]  # Partially filled grid with free cells marked as '_'

    def check_latin_square(grid):
        for i in range(3):
            if len(set(grid[i])) != 3 or len(set(grid[j][i] for j in range(3))) != 3:
                return False
        return True

    def encode_cell(value, cell_index):
        b0, b1 = value & 1, (value >> 1) & 1
        qc.x(problem_qubits[2 * cell_index] ^ b0)
        qc.x(problem_qubits[2 * cell_index + 1] ^ b1)

    def decode_cell(cell_index):
        b0 = qc.measure(problem_qubits[2 * cell_index])
        b1 = qc.measure(problem_qubits[2 * cell_index + 1])
        return (b0 + 2 * b1) % 3

    def oracle():
        for i in range(n_free_cells):
            encode_cell(rows[i], i)

        if check_latin_square(rows):
            qc.x(ancilla_qubits[0])

        for i in range(n_free_cells):
            decode_cell(i)

    oracle()
