from qiskit import QuantumCircuit
import numpy as np

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n_free_cells = len(problem_qubits) // 2
    rows = [0b00, 0b10, 0b11]
    cols = [0b00, 0b01, 0b10]

    def check_latin_square(grid):
        for i in range(3):
            if len(set(grid[i])) != 3:
                return False
            if len(set(grid[j][i] for j in range(3))) != 3:
                return False
        return True

    def encode_grid(grid):
        encoded = 0
        for i in range(3):
            for j in range(3):
                if grid[i][j] != -1:
                    encoded |= (grid[i][j] << (2 * (i * 3 + j)))
        return encoded

    def decode_value(value):
        return value & 0b11

    def is_valid_placement(grid, row, col, value):
        for i in range(3):
            if grid[row][i] == value or grid[i][col] == value:
                return False
        return True

    def find_next_empty_cell(grid):
        for i in range(3):
            for j in range(3):
                if grid[i][j] == -1:
                    return i, j
        return None, None

    def backtrack(grid, cell_index):
        if cell_index >= n_free_cells:
            return check_latin_square(grid)

        row, col = find_next_empty_cell(grid)
        if row is None:
            return False

        for value in range(3):
            if is_valid_placement(grid, row, col, value):
                grid[row][col] = value
                if backtrack(grid, cell_index + 1):
                    return True
                grid[row][col] = -1

        return False

    initial_grid = [
        [-1, 2, 1],
        [2, 1, 0],
        [1, 0, -1]
    ]

    if not backtrack(initial_grid, 0):
        raise ValueError("No solution found")

    encoded_grid = encode_grid(initial_grid)

    for j in range(n_free_cells):
        code = encoded_grid >> (2 * j) & 0b11
        value = decode_value(code)
        if value == 0:
            continue

        a = ancilla_qubits[j]
        qc.x(problem_qubits[2 * j])
        qc.cx(problem_qubits[2 * j + 1], a)
        qc.mcp(np.pi / 2, [problem_qubits[2 * j]], a)
        qc.cx(problem_qubits[2 * j + 1], a)
        qc.x(problem_qubits[2 * j])

    for a in ancilla_qubits:
        qc.reset(a)
