def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n = len(problem_qubits)
    T = 10
    target_bits = bin(T)[2:].zfill(n)

    def adder(circuit, a, b, cin, cout):
        carry = cin
        for i in range(len(a)):
            circuit.ccx(a[i], b[i], carry)
            circuit.cx(b[i], carry)
            circuit.cx(a[i], b[i])
            circuit.ccx(carry, a[i], b[i])
            carry = a[i]
        circuit.cx(carry, cout)

    def subtractor(circuit, a, b, cin, cout):
        carry = cin
        for i in range(len(a)):
            circuit.ccx(a[i], b[i], carry)
            circuit.cx(b[i], carry)
            circuit.cx(a[i], b[i])
            circuit.ccx(carry, a[i], b[i])
            carry = a[i]
        circuit.cx(carry, cout)

    def comparator(circuit, a, b, c):
        for i in range(len(a)):
            circuit.ccx(a[i], b[i], c[i])

    def add_constant(circuit, a, const):
        binary_const = bin(const)[2:].zfill(len(a))
        for i in range(len(a)):
            if binary_const[i] == '1':
                circuit.cx(ancilla_qubits[i], a[i])

    def subtract_constant(circuit, a, const):
        binary_const = bin(const)[2:].zfill(len(a))
        for i in range(len(a)):
            if binary_const[i] == '1':
                circuit.cx(ancilla_qubits[i], a[i])

    def check_sum(circuit, a, target_bits):
        for i in range(len(target_bits)):
            if target_bits[i] == '1':
                circuit.cx(a[i], ancilla_qubits[len(a)])

    def uncompute_addition(circuit, a, b, cin, cout):
        carry = cin
        for i in range(len(a)-1, -1, -1):
            circuit.cx(a[i], b[i])
            circuit.ccx(carry, a[i], b[i])
            circuit.cx(b[i], carry)
            circuit.ccx(a[i], b[i], carry)
            carry = a[i]
        circuit.cx(carry, cout)

    def uncompute_subtraction(circuit, a, b, cin, cout):
        carry = cin
        for i in range(len(a)-1, -1, -1):
            circuit.cx(a[i], b[i])
            circuit.ccx(carry, a[i], b[i])
            circuit.cx(b[i], carry)
            circuit.ccx(a[i], b[i], carry)
            carry = a[i]
        circuit.cx(carry, cout)

    def uncompute_comparator(circuit, a, b, c):
        for i in range(len(a)):
            circuit.ccx(c[i], a[i], b[i])

    def uncompute_check_sum(circuit, a, target_bits):
        for i in range(len(target_bits)):
            if target_bits[i] == '1':
                circuit.cx(a[i], ancilla_qubits[len(a)])

    # Initialize ancilla qubits to 0
    for q in ancilla_qubits:
