    add_constant(qc, problem_qubits, T)

    # Check if the sum equals T
    check_sum(qc, problem_qubits, target_bits)

    # Uncompute addition
    uncompute_addition(qc, problem_qubits, problem_qubits, 0, ancilla_qubits[len(problem_qubits)])

