from qiskit import QuantumCircuit
from qiskit.circuit.library import MCX

def build_oracle(qc: QuantumCircuit, problem_qubits: list[int], ancilla_qubits: list[int]) -> None:
    n_free_cells = len(problem_qubits) // 2
    ancilla = ancilla_qubits[0]

    def check_row(row, col):
        return (qc.measurements[row][col] != qc.measurements[row][(col + 1) % 3])

    def check_col(row, col):
        return (qc.measurements[row][col] != qc.measurements[(row + 1) % 3][col])

    def check_diagonals():
        return ((qc.measurements[0][0] != qc.measurements[1][1]) and 
                (qc.measurements[0][0] != qc.measurements[2][2]) and 
                (qc.measurements[0][2] != qc.measurements[1][1]) and 
                (qc.measurements[0][2] != qc.measurements[2][0]))

    def check_latin_square():
        for row in range(3):
            if not check_row(row, 0):
                return False
        for col in range(3):
            if not check_col(0, col):
                return False
        return check_diagonals()

    def oracle_circuit():
        for j in range(n_free_cells):
            b0 = problem_qubits[2*j]
            b1 = problem_qubits[2*j + 1]
            qc.mcx([b0, b1], ancilla)
        qc.z(ancilla)
        qc.mcx([b0, b1], ancilla)

    oracle_circuit()
    qc.barrier()
    qc.measure_all()
    qc.reset(range(len(problem_qubits)))
    qc.barrier()
    oracle_circuit()
